                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Residual %"
                  tick={{ fill: SLATE, fontSize: 12 }}
                  label={{
                    value: "Residual share %",
                    angle: -90,
                    position: "insideLeft",
                    fill: SLATE,
                    fontSize: 11,
