"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CHANNEL_SPLITS,
  EXIT_PRESSURE,
  HEADLINE,
  NATIONAL_CONTEXT,
  PACE_LADDER,
  SOURCE_NOTE,
  SOURCES,
  STATE_COMPARE,
  fmtM,
  fmtPct,
  fmtPp,
  seriesFor,
  type StateId,
} from "@/data/admitted-homeowners-insurers-exiting-coastal-states-2026-data";

// viz-types: residual share composed (area+line), channel stacked bars, exit-pressure scatter, pace horizontal bars, channel pie | layout: default

type ViewId = "timeline" | "channels" | "pressure" | "pace" | "mix";
type SeriesMetric =
  | "residualPremiumSharePct"
  | "admittedPremiumSharePct"
  | "residualPolicies";

const SKY = "#0ea5e9";
const AMBER = "#f59e0b";
const ROSE = "#f43f5e";
const EMERALD = "#10b981";
const SLATE = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function AdmittedHomeownersInsurersExitingCoastalStates2026Dashboard() {
  const [view, setView] = useState<ViewId>("timeline");
  const [stateId, setStateId] = useState<StateId>("FL");
  const [metric, setMetric] =
    useState<SeriesMetric>("residualPremiumSharePct");
  const [channelYear, setChannelYear] = useState<2018 | 2023>(2023);

  const series = useMemo(() => seriesFor(stateId), [stateId]);
  const stateMeta = STATE_COMPARE.find((s) => s.id === stateId)!;

  const timelineData = useMemo(
    () =>
      series.map((r) => ({
        year: r.year,
        residualShare: r.residualPremiumSharePct,
        admittedShare: r.admittedPremiumSharePct,
        policiesK: Math.round(r.residualPolicies / 1000),
        premiumM: r.residualPremiumM,
        confidence: r.confidence,
      })),
    [series],
  );

  const channelBars = useMemo(() => {
    return CHANNEL_SPLITS.filter((c) => c.year === channelYear).map((r) => {
      const label = STATE_COMPARE.find((s) => s.id === r.state)?.short ?? r.state;
      return {
        state: label,
        Admitted: r.admittedPct,
        Residual: r.residualPct,
        Surplus: r.surplusPct,
      };
    });
  }, [channelYear]);

  const scatterData = useMemo(
    () =>
      EXIT_PRESSURE.map((e) => ({
        ...e,
        x: e.appetiteIndex,
        y: e.residualSharePct,
        z: e.nonrenewalPressure,
        fill: e.state === "FL" ? SKY : e.state === "CA" ? AMBER : ROSE,
      })),
    [],
  );

  const paceBars = useMemo(
    () =>
      [...PACE_LADDER].sort(
        (a, b) => Math.abs(b.ppPerYear) - Math.abs(a.ppPerYear),
      ),
    [],
  );

