  const channelBars = useMemo(
    () =>
      CHANNEL_SPLITS.filter((c) => c.year === channelYear).map((r) => ({
        state: STATE_COMPARE.find((s) => s.id === r.state)?.short ?? r.state,
        Admitted: r.admittedPct,
