const fs = require("fs");
const dash = fs.readFileSync(
  "src/components/visualizations/AdmittedHomeownersInsurersExitingCoastalStates2026Dashboard.tsx",
  "utf8",
);
const data = fs.readFileSync(
  "src/data/admitted-homeowners-insurers-exiting-coastal-states-2026-data.ts",
  "utf8",
);
const imp = dash.match(/import \{([\s\S]*?)\} from "@\/data\/admitted[^"]+"/)[1];
const names = imp
  .split(",")
  .map((s) => s.trim().replace(/^type /, "").replace(/\s+/g, ""))
  .filter(Boolean);
const exports = new Set(
  [...data.matchAll(/export (?:const|function|type) (\w+)/g)].map((m) => m[1]),
);
console.log("imports:", names);
for (const n of names) console.log(n, exports.has(n) ? "OK" : "MISSING");
console.log(
  "appetiteIndex in data",
  data.includes("appetiteIndex"),
  "in dash",
  dash.includes("appetiteIndex"),
);
console.log(
  "ppPerYear in data",
  data.includes("ppPerYear"),
  "in dash",
  dash.includes("ppPerYear"),
);
console.log(
  "admittedPct in data",
  data.includes("admittedPct"),
